SourceCode.Declaration:
/// <summary>
/// Data contract class for transfer picking list generation service task
/// </summary>
[DataContractAttribute]
class METTransferPickingListGenerationTaskContract
{
    container               oscCodeList;
    InventTransferId        transferId;
    boolean                 triggerBusinessEvent;
    boolean                 skipFinalisationProcess;
    container               conShipmentIds;

    // Task 424597
    boolean                         overridePickingListParms;
    NoYes                           reservation;
    InventTransferPickUpdateQty     pickUpdateQty;

}

Method.Source:
/// <summary>
/// Parameter method to set or get skip finalisation process flag
/// </summary>
/// <param name = "_skipFinalisationProcess">Boolean flag</param>
/// <returns>Boolean result</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public boolean parmSkipFinalisationProcess(boolean _skipFinalisationProcess = skipFinalisationProcess)
{
    skipFinalisationProcess = _skipFinalisationProcess;
    return skipFinalisationProcess;
}

/// <summary>
/// Parameter method to set or get list of shipmentd's
/// </summary>
/// <param name = "_conShipmentIds">Container value</param>
/// <returns>Boolean value</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public container parmShipmentIdList(container _conShipmentIds = conShipmentIds)
{
    conShipmentIds = _conShipmentIds;
    return conShipmentIds;
}

    /// <summary>
    /// OSCCode list which contains the list of OSCCode need to be processed
    /// </summary>
    /// <param name = "_oscCodeList">OSCCode list</param>
    /// <returns>OSCCode list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmOSCCodeList(container _oscCodeList = oscCodeList)
    {
        oscCodeList = _oscCodeList;

        return oscCodeList;
    }

    /// <summary>
    /// Transfer Id which need to be processed
    /// </summary>
    /// <param name = "_transferId">Transfer Id</param>
    /// <returns>Transfer Id</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public InventTransferId parmTransferId(InventTransferId _transferId = transferId)
    {
        transferId = _transferId;

        return transferId;
    }

    /// <summary>
    /// get Caption for the batch job task based on transfer id and OSC code
    /// </summary>
    /// <returns>batch job caption</returns>
    public str getCaption()
    {
        int i;
        str caption = strFmt('%1 - ', this.parmTransferId());

        for(i = 1; i <= conLen(this.parmOSCCodeList()); i++)
        {
            if(i != 1)
            {
                caption += ', ';
            }
            caption += conPeek(this.parmOSCCodeList(), i);
        }
        return caption;
    }

/// <summary>
/// Parameter method to set or get business event trigger flag
/// </summary>
/// <param name = "_triggerBusinessEvent">Boolean value</param>
/// <returns>Boolean value</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public boolean parmTriggerBusinessEvent(boolean _triggerBusinessEvent = triggerBusinessEvent)
{
    triggerBusinessEvent = _triggerBusinessEvent;
    return triggerBusinessEvent;
}

/// <summary>
/// Task 424597: When true, Reservation and PickUpdateQty from this contract are applied.
/// Default false keeps legacy behaviour for METTransferPickingListGenerationService
/// (extraction screen) and METCrossDockTransferFinalizationFacade.
/// </summary>
/// <param name = "_overridePickingListParms">Override flag</param>
/// <returns>Override flag</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public boolean parmOverridePickingListParms(boolean _overridePickingListParms = overridePickingListParms)
{
    overridePickingListParms = _overridePickingListParms;
    return overridePickingListParms;
}

/// <summary>
/// Task 424597: Reservation flag passed from the batch job.
/// </summary>
/// <param name = "_reservation">Reservation flag</param>
/// <returns>Reservation flag</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public NoYes parmReservation(NoYes _reservation = reservation)
{
    reservation = _reservation;
    return reservation;
}

/// <summary>
/// Task 424597: Picking list update quantity passed from the batch job.
/// </summary>
/// <param name = "_pickUpdateQty">Picking list update quantity</param>
/// <returns>Picking list update quantity</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public InventTransferPickUpdateQty parmPickUpdateQty(InventTransferPickUpdateQty _pickUpdateQty = pickUpdateQty)
{
    pickUpdateQty = _pickUpdateQty;
    return pickUpdateQty;
}
